public class Main {
    public static void main(String[] args) {
        int day = 6;
        switch (day) {                  // old style: several labels, break needed
            case 6:
            case 7:
                System.out.println("Weekend");
                break;
            default:
                System.out.println("Weekday");
        }

        String name = switch (day) {    // switch as an expression gives a value
            case 1, 7 -> "Edge of week";
            case 6 -> "Saturday";
            default -> {
                String t = "Day " + day;
                yield t;                // yield returns from a block
            }
        };
        System.out.println(name);

        int fall = 1;
        switch (fall) {                 // no break: execution "falls through"
            case 1: System.out.println("one");
            case 2: System.out.println("two (fall-through!)"); break;
            case 3: System.out.println("three");
        }
    }
}

