public class Main {
    public static void main(String[] args) {
        System.out.println(sum() + " " + sum(5) + " " + sum(1, 2, 3, 4));
        System.out.println(max(new int[]{4, 9, 2}));
        int[] result = minMax(new int[]{7, 3, 9, 1});
        System.out.println(result[0] + " " + result[1]);
        System.out.println(isPrime(29) + " " + isPrime(30) + " " + isPrime(1));
    }

    static int sum(int... numbers) {              // any number of arguments
        int total = 0;
        for (int n : numbers) total += n;
        return total;
    }

    static int max(int[] values) {
        int best = values[0];
        for (int v : values) if (v > best) best = v;
        return best;
    }

    static int[] minMax(int[] values) {           // return several values in an array
        int min = values[0], max = values[0];
        for (int v : values) {
            if (v < min) min = v;
            if (v > max) max = v;
        }
        return new int[]{min, max};
    }

    static boolean isPrime(int n) {
        if (n < 2) return false;                  // early return
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }
}

