            infinite(1);
        } catch (StackOverflowError e) {
            System.out.println("Too deep: a base case is missing");
        }
    }

    static long factorial(int n) { return n <= 1 ? 1 : n * factorial(n - 1); }
    static int fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }
    static int power(int base, int exp) { return exp == 0 ? 1 : base * power(base, exp - 1); }
    static int digitSum(int n) { return n == 0 ? 0 : n % 10 + digitSum(n / 10); }

    static void countdown(int n) {
        if (n == 0) { System.out.println("Go!"); return; }
        System.out.println(n);
        countdown(n - 1);
    }

    static int infinite(int n) { return infinite(n + 1); }
}

