        for (T item : items) if (item.compareTo(best) > 0) best = item;
        return best;
    }

    static void printAll(List<? extends Number> numbers) {            // wildcard
        double sum = 0;
        for (Number n : numbers) sum += n.doubleValue();
        System.out.println("sum = " + sum);
    }
}

