import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> nums = List.of(5, 12, 8, 3, 20, 8);
        System.out.println(nums.stream().filter(n -> n > 5).map(n -> n * 2).collect(Collectors.toList()));
        System.out.println(nums.stream().mapToInt(Integer::intValue).sum());
        System.out.println(nums.stream().mapToInt(n -> n).average().orElse(0));
        System.out.println(nums.stream().distinct().sorted().limit(3).toList());
        System.out.println(nums.stream().anyMatch(n -> n > 15) + " " + nums.stream().allMatch(n -> n > 0));
        System.out.println(IntStream.rangeClosed(1, 5).boxed().collect(Collectors.toList()));

        List<String> words = List.of("apple", "avocado", "banana", "blueberry", "cherry");
        System.out.println(words.stream().collect(Collectors.groupingBy(w -> w.charAt(0))));
        System.out.println(words.stream().map(String::toUpperCase).collect(Collectors.joining(", ", "[", "]")));
        System.out.println(words.stream().collect(Collectors.toMap(w -> w, String::length)).get("banana"));
        System.out.println(words.stream().filter(w -> w.length() > 5).count());
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    record Student(String name, String course, int marks) {}

    public static void main(String[] args) {
        List<Student> students = List.of(
            new Student("Ali", "Java", 78), new Student("Sara", "Java", 92),
            new Student("Bilal", "SQL", 65), new Student("Hira", "SQL", 88));

        System.out.println(students.stream().filter(s -> s.marks() >= 80).map(Student::name).toList());
        System.out.println(students.stream().mapToInt(Student::marks).max().getAsInt());
        System.out.println(students.stream().sorted(Comparator.comparingInt(Student::marks).reversed())
                .map(Student::name).collect(Collectors.joining(" > ")));

        Map<String, Double> avg = students.stream()
            .collect(Collectors.groupingBy(Student::course, TreeMap::new, Collectors.averagingInt(Student::marks)));
        System.out.println(avg);

        Optional<Student> top = students.stream().max(Comparator.comparingInt(Student::marks));
        System.out.println(top.map(Student::name).orElse("nobody"));
    }
}

