import java.util.*;

public class Main {
    public static void main(String[] args) {
        String csv = "name,marks\nAli,78\nSara,92\nBilal,65";       // imagine this came from a file
        String[] rows = csv.split("\n");
        int total = 0;
        Map<String, Integer> marks = new LinkedHashMap<>();
        for (int i = 1; i < rows.length; i++) {                      // skip the header row
            String[] cols = rows[i].split(",");
            int m = Integer.parseInt(cols[1].trim());
            marks.put(cols[0], m);
            total += m;
            System.out.println(cols[0] + " -> " + cols[1]);
        }
        System.out.println("Average: " + (double) total / marks.size());
        System.out.println("Best: " + Collections.max(marks.entrySet(), Map.Entry.comparingByValue()).getKey());
    }
}

